func VerifyImageURL404Resolved(ctx context.Context, db *sql.DB, spec map[string]interface{}, logger *zap.Logger) (VerifyResult, error) {
    url, _ := spec["image_url"].(string)
    if url == "" {
        return VerifyResult{}, fmt.Errorf("image_url_404 spec has no image_url")
    }
    // HEAD with a short timeout bounded by ctx.
    // 2xx/3xx  -> VerifyResult{Resolved: true,  Detail: "HTTP <code>"}
    // 404/410   -> VerifyResult{Resolved: false, Detail: "still HTTP <code>"}
    // transport error / timeout / 5xx -> return VerifyResult{}, err
    //   (fail OPEN per the gate's policy - never report a transient failure as
    //    'defect persists', which would burn an attempt on a fixed item)
}

